function handlePostOrder(httpRequest) {
  body = JSON.parse(httpRequest.body)
  if (body.items.length > 10) return http(400, "Слишком много")   // правило бизнеса
  row = sql("INSERT INTO orders ...", body)                        // база
  smtp.send("kitchen@cafe", "Новый заказ " + row.id)                // почта
  return http(201, row)
}
